// Each fighter's view of a recorded match, for learning from the ladder's games (imitation,
// offline RL, analysis). A replay holds only the turns the server resolved; re-running it through
// MatchCore, the code the server ran it on, gives back what each bot was sent.

import { checkCompatible, type Observation, type RecordedTurn, type Replay } from "@arena/engine";
import type { EndMsg, HelloMsg } from "@arena/protocol";
import { MatchCore, recordedOutcome, type TurnOutcome } from "./match.ts";
import { wire } from "./wire.ts";

export interface Trajectory {
  hello: HelloMsg;
  /** each tick: the observation the bot was sent, and the turn the server took from its reply
   *  (with `reason` when it was idle because of a timeout, a bad message, a disconnection...) */
  steps: { observation: Observation; turn: RecordedTurn }[];
  /** the end message, or null for a replay that stops before the match ended */
  end: EndMsg | null;
}

/**
 * Each fighter's trajectory in a recorded match, by fighter id. Exact but for what a replay
 * doesn't record: `budget_ms_left` (wall-clock time) stays at the match budget, `match_id` is
 * "replay", the deadlines in `hello` are the rules' defaults, the events for a refused message have
 * no `detail` text, and a match the server ended early (a disqualification) lacks the observation
 * it sent last, whose reply never resolved.
 * Throws for a replay from another engine version or rules table.
 */
export function replayTrajectories(replay: Replay): Record<number, Trajectory> {
  const { header } = replay;
  const { rules, map } = checkCompatible(header);
  const seats = header.bots.map((b) => ({ fighterId: b.id, name: b.name, version: b.version }));
  const core = new MatchCore({
    matchId: "replay",
    rules,
    map,
    seed: header.seed,
    limits: rules.limits,
    seats,
  });
  const out: Record<number, Trajectory> = Object.fromEntries(
    seats.map((s) => [s.fighterId, { hello: wire(core.hello(s.fighterId)), steps: [], end: null }]),
  );
  for (const t of replay.ticks) {
    if (core.result) throw new Error(`replay: tick ${t.tick} recorded after the match ended`);
    if (t.tick !== core.state.tick)
      throw new Error(`replay: tick ${t.tick} recorded where tick ${core.state.tick} was expected`);
    const outcomes: Record<number, TurnOutcome> = {};
    for (const s of seats) {
      const turn = t.turns[String(s.fighterId)] ?? { reason: "timeout" };
      out[s.fighterId]!.steps.push({ observation: wire(core.takeObservation(s.fighterId)), turn });
      outcomes[s.fighterId] = recordedOutcome(turn);
    }
    core.resolve(outcomes);
  }
  // A match the server ended (a forfeit, a disqualification) has its result after the last tick.
  if (!core.result && replay.result) core.endWith(replay.result);
  if (core.result) {
    const summary = core.summary();
    for (const s of seats)
      out[s.fighterId]!.end = wire(core.endMessage(s.fighterId, summary, null));
  }
  return out;
}
