// Shouts are cleaned here, where a reply becomes a turn, so the replay records what was shown and
// re-simulating it never depends on this word list: changing the filter can't break old replays.

import {
  RegExpMatcher,
  TextCensor,
  asteriskCensorStrategy,
  englishDataset,
  englishRecommendedTransformers,
} from "obscenity";

const matcher = new RegExpMatcher({ ...englishDataset.build(), ...englishRecommendedTransformers });
const censor = new TextCensor().setStrategy(asteriskCensorStrategy());

// Controls, invisible formatting (zero-width, bidi overrides, soft hyphen), noncharacters and lone
// surrogates. Spelled out rather than \p{C}: the simulator also runs on V8 without ICU.
const INVISIBLE =
  /[\u0000-\u001f\u007f-\u009f­͏؜ᅟᅠ឴឵᠋-᠏​-‏‪-‮⁠-⁯ㅤ︀-️﻿ﾠ￰-￿]|[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/g;

/**
 * A shout as everyone will see it: lookalike letters folded (where the runtime can), invisible
 * characters removed, runs of spaces collapsed and profanity masked with *. The engine then checks
 * its length, so a shout that cleans down to nothing is refused rather than shown blank.
 */
export function cleanShout(text: string): string {
  let s = text;
  try {
    s = s.normalize("NFKC");
  } catch {
    // no ICU: the matcher's own transformers still fold most lookalikes
  }
  s = s.replace(INVISIBLE, "").replace(/\s+/g, " ").trim();
  return censor.applyTo(s, matcher.getAllMatches(s));
}
