// One match as the server plays it, without sockets or clocks: the hello, each fighter's
// observation (with the server's own events and the budget left), how each reply counts,
// failure counting and disqualification, forfeits, the replay and the end message.
// The server's MatchRunner adds connections, deadlines and reconnects on top; a simulator
// drives this directly, so a bot sees the same messages in training as on the ladder.

import {
  ENGINE_VERSION,
  cloneState,
  createMatch,
  forceEnd,
  makeHeader,
  observe,
  pickupPads,
  replayStats,
  REPLAY_FORMAT_VERSION,
  stateHash,
  step,
  type GameEvent,
  type GameMap,
  type MatchResult,
  type MatchState,
  type MatchStats,
  type Observation,
  type RecordedTurn,
  type Replay,
  type Rules,
  type TurnInput,
} from "@arena/engine";
import {
  PROTOCOL_VERSION,
  parseBotMessage,
  type EndMsg,
  type HelloMsg,
  type TurnMsg,
} from "@arena/protocol";
import { cleanShout } from "./shout.ts";
import { RELEASE } from "./version.ts";

export type Limits = Rules["limits"];

export interface SeatInfo {
  fighterId: number;
  name: string;
  version: string;
}

export interface ScriptedSeat extends SeatInfo {
  /** recorded turn for a tick, or undefined once the script runs out */
  turnFor(tick: number): TurnInput | undefined;
}

export interface MatchCoreOptions {
  matchId: string;
  rules: Rules;
  map: GameMap;
  seed: number;
  limits: Limits;
  seats: SeatInfo[];
  scripted?: ScriptedSeat[];
  /** start from this state instead of a fresh match (replay --from) */
  initialState?: MatchState;
  /** recorded ticks to prepend to the replay when starting mid-match */
  prefixTicks?: Replay["ticks"];
  log?: (line: string) => void;
  onTick?: (state: MatchState) => void;
  /** record each tick's state hash in the replay (default true); hashing costs more than the tick itself, so training turns it off */
  hashes?: boolean;
}

export interface MatchSummary {
  matchId: string;
  result: MatchResult;
  voided: boolean;
  replay: Replay;
  /** what each fighter did, counted from the replay */
  stats: MatchStats;
}

/** How one fighter's reply counts for a tick. A failed reply counts toward disqualification. */
export interface TurnOutcome {
  turn: TurnInput;
  reason?: string;
  detail?: string;
  failed: boolean;
}

/** No usable reply before the deadline. */
export function timeoutOutcome(): TurnOutcome {
  return { turn: {}, reason: "timeout", failed: true };
}

/** A frame that failed JSON or schema validation. */
export function malformedOutcome(code: string, detail?: string): TurnOutcome {
  return { turn: {}, reason: code, detail, failed: true };
}

/** Reasons for an idle turn that don't count toward disqualification: the bot wasn't there to answer. */
const NOT_FAILURES = new Set(["disconnected", "budget_exhausted", "script_end"]);

/** The outcome a replay's recorded turn stands for; its `reason` says why the server made it idle. */
export function recordedOutcome(recorded: RecordedTurn): TurnOutcome {
  const { reason, ms: _ms, ...turn } = recorded;
  return reason ? { turn, reason, failed: !NOT_FAILURES.has(reason) } : { turn, failed: false };
}

/** How a valid turn message counts for `tick`, or null for a late reply echoing an older tick, which is discarded. */
export function replyOutcome(msg: TurnMsg, tick: number): TurnOutcome | null {
  if (msg.tick < tick) return null;
  if (msg.tick > tick)
    return {
      turn: {},
      reason: "wrong_tick",
      detail: `replied for tick ${msg.tick}, the current tick is ${tick}`,
      failed: true,
    };
  const { tick: _t, type: _type, ...turn } = msg;
  if (turn.shout !== undefined) turn.shout = cleanShout(turn.shout);
  return { turn, failed: false };
}

/**
 * How a bot's only frame for `tick` counts, as the server would take it: null is no reply.
 * A frame the server discards or ignores in a match (an old tick, `ready`, `queue`) leaves
 * the tick waiting for its deadline, so it is a timeout.
 */
export function frameOutcome(frame: string | null, tick: number): TurnOutcome {
  if (frame === null) return timeoutOutcome();
  const parsed = parseBotMessage(frame);
  if (!parsed.ok) return malformedOutcome(parsed.code, parsed.message);
  if (parsed.value.kind !== "turn") return timeoutOutcome();
  return replyOutcome(parsed.value.msg, tick) ?? timeoutOutcome();
}

interface Seat extends SeatInfo {
  budgetMs: number;
  failures: number;
  /** server-side problems to report in the next observation */
  pendingEvents: GameEvent[];
  /** reply time charged this tick, recorded with its turn */
  chargedMs?: number;
}

export class MatchCore {
  readonly opts: MatchCoreOptions;
  readonly state: MatchState;
  private seats: Seat[];
  private replay: Replay;
  private voided = false;
  private summaryCache: MatchSummary | null = null;
  private log: (line: string) => void;

  constructor(opts: MatchCoreOptions) {
    this.opts = opts;
    this.log = opts.log ?? (() => {});
    this.state = opts.initialState
      ? cloneState(opts.initialState)
      : createMatch(opts.rules, opts.map, opts.seed);
    this.seats = opts.seats.map((s) => ({
      fighterId: s.fighterId,
      name: s.name,
      version: s.version,
      budgetMs: opts.limits.match_budget_ms,
      failures: 0,
      pendingEvents: [],
    }));
    const bots = [...opts.seats, ...(opts.scripted ?? [])]
      .map((s) => ({ id: s.fighterId, name: s.name, version: s.version }))
      .sort((a, b) => a.id - b.id);
    this.replay = {
      header: {
        ...makeHeader(opts.rules, opts.map, opts.seed, bots),
        release: RELEASE,
        replay_format: REPLAY_FORMAT_VERSION,
      },
      ticks: [...(opts.prefixTicks ?? [])],
      result: null,
    };
  }

  get result(): MatchResult | null {
    return this.state.result;
  }

  private seat(fighterId: number): Seat {
    const s = this.seats.find((x) => x.fighterId === fighterId);
    if (!s) throw new Error(`match: no seat for fighter ${fighterId}`);
    return s;
  }

  private opponent(fighterId: number): SeatInfo {
    return [...this.seats, ...(this.opts.scripted ?? [])].find((x) => x.fighterId !== fighterId)!;
  }

  hello(fighterId: number): HelloMsg {
    const opp = this.opponent(fighterId);
    const { limits } = this.opts;
    return {
      type: "hello",
      protocol_version: PROTOCOL_VERSION,
      match_id: this.opts.matchId,
      bot_id: fighterId,
      opponent: { bot_id: opp.fighterId, name: opp.name },
      rules: this.opts.rules as unknown as Record<string, unknown>,
      map: this.opts.map.tiles,
      map_name: this.opts.map.name,
      pickups: pickupPads(this.opts.map),
      seed_public: this.opts.seed,
      engine_version: ENGINE_VERSION,
      deadlines: {
        startup_ms: limits.startup_ms,
        tick_ms: limits.tick_ms,
        match_budget_ms: limits.match_budget_ms,
      },
    };
  }

  /** The current observation for a fighter, without using up its pending server events (a resend on reconnect). */
  observation(fighterId: number): Observation {
    const s = this.seat(fighterId);
    const obs = observe(this.state, fighterId);
    obs.self.budget_ms_left = s.budgetMs;
    obs.events = [...s.pendingEvents, ...obs.events];
    return obs;
  }

  /** The observation that asks a fighter for this tick's turn; its pending server events are delivered with it. */
  takeObservation(fighterId: number): Observation {
    const obs = this.observation(fighterId);
    this.seat(fighterId).pendingEvents = [];
    return obs;
  }

  budgetLeft(fighterId: number): number {
    return this.seat(fighterId).budgetMs;
  }

  /** Spends response time from a fighter's match budget; the replay records it with this tick's turn. */
  charge(fighterId: number, ms: number): void {
    const s = this.seat(fighterId);
    s.budgetMs = Math.max(0, s.budgetMs - ms);
    s.chargedMs = (s.chargedMs ?? 0) + ms;
  }

  /**
   * Resolves the current tick from each seat's outcome. `forfeited` lists seats that left for
   * good (out of reconnect time). Returns the result once the match is over.
   */
  resolve(outcomes: Record<number, TurnOutcome>, forfeited: number[] = []): MatchResult | null {
    if (this.state.result) throw new Error("match is over");
    const tick = this.state.tick;
    const turns: Record<number, TurnInput> = {};
    const recorded: Record<string, RecordedTurn> = {};
    let dq: Seat | null = null;
    for (const s of this.seats) {
      const o = outcomes[s.fighterId] ?? timeoutOutcome();
      turns[s.fighterId] = o.turn;
      recorded[String(s.fighterId)] = {
        ...o.turn,
        ...(o.reason ? { reason: o.reason } : {}),
        ...(s.chargedMs !== undefined ? { ms: s.chargedMs } : {}),
      };
      s.chargedMs = undefined;
      if (o.reason && o.reason !== "disconnected") {
        s.pendingEvents.push({
          kind: "rejected",
          fighter: s.fighterId,
          part: "(message)",
          reason: o.reason,
          ...(o.detail ? { detail: o.detail } : {}),
        });
      }
      s.failures = o.failed ? s.failures + 1 : 0;
      if (s.failures >= this.opts.limits.max_consecutive_failures && !dq) dq = s;
    }
    for (const sc of this.opts.scripted ?? []) {
      const a = sc.turnFor(tick);
      turns[sc.fighterId] = a ?? {};
      recorded[String(sc.fighterId)] = a ?? { reason: "script_end" };
    }
    if (
      forfeited.length > 0 &&
      forfeited.length === this.seats.length &&
      !this.opts.scripted?.length
    ) {
      // Everyone left: nobody wins.
      this.state.result = { winner: null, reason: "forfeit", final_tick: tick };
    } else if (forfeited.length > 0) {
      forceEnd(this.state, forfeited[0]!, "forfeit");
    } else if (dq) {
      const d = dq as Seat;
      this.log(`bot ${d.name} failed ${d.failures} consecutive ticks: disqualified`);
      forceEnd(this.state, d.fighterId, "disqualified");
    } else {
      step(this.state, turns);
      this.replay.ticks.push({
        type: "tick",
        tick,
        turns: recorded,
        ...(this.opts.hashes === false ? {} : { hash: stateHash(this.state) }),
      });
      this.opts.onTick?.(this.state);
    }
    return this.state.result;
  }

  /** Ends the match with a result decided outside it: one recorded in a replay (a forfeit, a disqualification). */
  endWith(result: MatchResult): void {
    if (this.state.result) throw new Error("match is over");
    this.state.result = {
      winner: result.winner,
      reason: result.reason,
      final_tick: result.final_tick,
    };
  }

  /**
   * Seats that never sent `ready` forfeit at tick 0. One no-show loses like any forfeit, so
   * declining an opponent after `hello` names it costs a loss; when neither seat is ready
   * there is no one to blame and the match is voided.
   */
  forfeitBeforeStart(fighterIds: number[]): MatchResult {
    if (fighterIds.length === 1) return forceEnd(this.state, fighterIds[0]!, "forfeit");
    this.voided = true;
    this.state.result = { winner: null, reason: "forfeit", final_tick: this.state.tick };
    return this.state.result;
  }

  summary(): MatchSummary {
    const result = this.state.result;
    if (!result) throw new Error("match is not over");
    if (!this.summaryCache) {
      this.replay.result = { type: "result", ...result };
      this.summaryCache = {
        matchId: this.opts.matchId,
        result,
        voided: this.voided,
        replay: this.replay,
        stats: replayStats(this.replay),
      };
    }
    return this.summaryCache;
  }

  endMessage(fighterId: number, summary: MatchSummary, replayUrl: string | null): EndMsg {
    const { result } = summary;
    return {
      type: "end",
      match_id: summary.matchId,
      result: result.winner === null ? "draw" : result.winner === fighterId ? "win" : "loss",
      reason: result.reason,
      final_tick: result.final_tick,
      opponent_version: this.opponent(fighterId).version,
      replay_url: replayUrl,
      rating_change: null,
      ...(summary.voided ? { voided: true } : { stats: summary.stats }),
    };
  }
}
