// Many games stepped in one call, for driving the simulator from another language. A call across
// a language boundary costs far more than a tick (about 180 µs from Python into embedded V8,
// against about 30 µs a tick), so the caller steps a whole batch per call. Messages go out as the
// JSON frames the ladder sends, spliced into one JSON document so the other side parses once.

import { Game, type GameOptions, type Reply } from "./game.ts";

export class Batch {
  private games: (Game | null)[];

  constructor(size: number) {
    this.games = Array.from({ length: size }, () => null);
  }

  get size(): number {
    return this.games.length;
  }

  /** Starts a game in slot `i`, replacing any game there. Returns JSON: `{"hello": {id: hello}, "next": {id: observation}}` for each fighter you play. */
  start(i: number, options: GameOptions = {}): string {
    if (!Number.isInteger(i) || i < 0 || i >= this.games.length)
      throw new Error(`no slot ${i} (the batch has ${this.games.length})`);
    const game = (this.games[i] = new Game(options));
    const hello = game.players.map((id) => `"${id}":${JSON.stringify(game.hello(id))}`).join(",");
    return `{"hello":{${hello}},"next":${this.frames(game)}}`;
  }

  /**
   * Steps games with their players' replies, as JSON: an array by slot of `{fighterId: reply}`, or
   * null to leave that game alone. Returns JSON: by slot, what each player is sent next
   * (`{fighterId: observation or end}`), or null for a game not stepped.
   */
  step(replies: string): string {
    const all = JSON.parse(replies) as (Record<string, Reply> | null)[];
    if (!Array.isArray(all) || all.length !== this.games.length)
      throw new Error(
        `step takes an array of ${this.games.length} replies (one per slot, null to skip)`,
      );
    const out = all.map((r, i) => {
      if (r === null) return "null";
      const game = this.game(i);
      game.step(r as Record<number, Reply>);
      return this.frames(game);
    });
    return `[${out.join(",")}]`;
  }

  /** The game in slot `i`, for its result, summary and replay. */
  game(i: number): Game {
    const game = this.games[i];
    if (!game) throw new Error(`no game in slot ${i}: start one first`);
    return game;
  }

  private frames(game: Game): string {
    return `{${game.players.map((id) => `"${id}":${game.nextFrame(id)}`).join(",")}}`;
  }
}
