// Diagnostics belong at the simulator boundary, never in the deterministic engine.
export type VectorPhase =
  | "actions"
  | "simulation"
  | "observation"
  | "encoding"
  | "teacher"
  | "wire"
  | "reset"
  | "other";

export interface VectorProfile {
  clock: "performance.now" | "Date.now";
  /** Date.now is a coarse, adjustable wall clock; negative deltas are clamped. */
  coarse: boolean;
  every: number;
  steps: number;
  sampled_steps: number;
  /** Counts and durations below describe sampled steps only. */
  games: number;
  resets: number;
  encoded_seats: number;
  /** All JavaScript step wall time, including unsampled steps. */
  elapsed_ms: number;
  total_ms: number;
  phases_ms: Record<VectorPhase, number>;
}

/** Internal recorder: a phase ends where the next one starts, so times never overlap. */
export class VectorProfiler {
  private read: () => number;
  private data: VectorProfile;
  private last = 0;
  private started = 0;
  private sampled = false;

  constructor(every: number) {
    if (!Number.isSafeInteger(every) || every < 1)
      throw new Error("profile.every must be a positive safe integer");
    const high = typeof globalThis.performance?.now === "function";
    this.read = high ? () => globalThis.performance.now() : () => Date.now();
    this.data = {
      clock: high ? "performance.now" : "Date.now",
      coarse: !high,
      every,
      steps: 0,
      sampled_steps: 0,
      games: 0,
      resets: 0,
      encoded_seats: 0,
      elapsed_ms: 0,
      total_ms: 0,
      phases_ms: {
        actions: 0,
        simulation: 0,
        observation: 0,
        encoding: 0,
        teacher: 0,
        wire: 0,
        reset: 0,
        other: 0,
      },
    };
  }

  begin(): VectorProfiler | null {
    this.started = this.last = this.read();
    this.sampled = this.data.steps++ % this.data.every === 0;
    if (!this.sampled) return null;
    this.data.sampled_steps++;
    return this;
  }

  mark(phase: VectorPhase): void {
    const now = Math.max(this.last, this.read());
    this.data.phases_ms[phase] += now - this.last;
    this.last = now;
  }

  game(): void {
    this.data.games++;
  }
  reset(): void {
    this.data.resets++;
  }
  encoded(): void {
    this.data.encoded_seats++;
  }

  end(): void {
    if (this.sampled) {
      this.mark("other");
      this.data.total_ms += this.last - this.started;
    } else {
      this.last = Math.max(this.started, this.read());
    }
    this.data.elapsed_ms += this.last - this.started;
  }

  snapshot(reset = false): VectorProfile {
    const out = { ...this.data, phases_ms: { ...this.data.phases_ms } };
    if (reset) {
      this.data.steps =
        this.data.sampled_steps =
        this.data.games =
        this.data.resets =
        this.data.encoded_seats =
        this.data.elapsed_ms =
        this.data.total_ms =
          0;
      for (const key of Object.keys(this.data.phases_ms) as VectorPhase[])
        this.data.phases_ms[key] = 0;
    }
    return out;
  }
}
