// The forward model: the engine's own tick, for bots that look ahead. A search bot builds a
// state from what it was told (`start` from the hello, `fromObservation` each tick, with its own
// guesses for what the fog hides), copies it, steps candidate turns and scores the result. The
// functions are the ones the ladder resolves matches with, so a step here is a step there.
//
// `forward.api` versions this contract. A state is plain JSON-safe data (the engine's
// `MatchState`, the same object the replay hashes are taken over), so a bot may read it, change
// it to fit what it believes, and pass it to another process or language.

import {
  ENGINE_VERSION,
  SUB,
  UNLIMITED_TRAVEL,
  cloneState,
  createMatch,
  loadRules,
  moveOptions,
  observe,
  stateHash,
  step,
  validateTurn,
  type Area,
  type FighterStateName,
  type GameEvent,
  type GameMap,
  type MatchState,
  type MoveOptions,
  type Observation,
  type Projectile,
  type ProjectileView,
  type Rules,
  type TurnInput,
  type Validation,
} from "@arena/engine";
import type { HelloMsg } from "@arena/protocol";
import { SHIPPED_MAPS } from "./shipped.ts";

/** The forward model's contract version. It changes when a function's arguments or results do. */
export const FORWARD_API_VERSION = 1;

/** A turn as a bot sends it (`tick` and `type` are allowed and ignored), by fighter id; a missing or null entry is an idle turn. */
export type ForwardTurns = Record<number, TurnInput | null | undefined>;

type AreaView = Observation["areas"][number];

/**
 * What a fighter believes about something the observation doesn't show it, in the observation's
 * own terms (ticks left rather than absolute ticks), so a guess reads like what it stands for.
 */
export interface FighterGuess {
  pos?: [number, number];
  hp?: number;
  /** every cooldown; the observation only shows an enemy's dash */
  cooldowns?: Record<string, number>;
  state?: FighterStateName;
  state_ticks_left?: number;
  /** pickup buffs: kind → ticks left, counting this tick */
  buffs?: Record<string, number>;
  /** consecutive ticks it ended outside the zone (zone damage grows with it) */
  ticks_outside?: number;
  /** hp it has dealt this match (only breaks a timeout tie on hp) */
  damage_dealt?: number;
}

/** Guesses for what the fog hides. Anything the observation shows wins over a guess. */
export interface Assumptions {
  /** your own fighter: only what the observation leaves out (`ticks_outside`, `damage_dealt`) */
  self?: Pick<FighterGuess, "ticks_outside" | "damage_dealt">;
  /** the opponent: required with `pos` while it is out of sight; in sight, fills what isn't shown */
  enemy?: FighterGuess;
  /** pads out of sight, by pad id: `ready_in` as an observation would show it (0 = stocked) */
  pickups?: Record<number, { ready_in: number }>;
  /** shots you believe are flying out of sight, in the observation's form */
  projectiles?: ProjectileView[];
  /** frost areas you believe are out of sight, in the observation's form (`tiles` not needed) */
  areas?: Omit<AreaView, "tiles">[];
}

/** The hello's map as the engine's map: the shipped map of that name, or `map` for one of your own. */
function helloMap(hello: HelloMsg, map?: GameMap): GameMap {
  const m = map ?? SHIPPED_MAPS.find((x) => x.name === hello.map_name);
  if (!m)
    throw new Error(
      `forward: map '${hello.map_name}' isn't one this simulator ships; pass the map object as well`,
    );
  if (m.tiles.length !== hello.map.length || m.tiles.some((row, y) => row !== hello.map[y]))
    throw new Error(
      `forward: the hello's map differs from this simulator's '${m.name}' (a newer release?); pass the map object as well`,
    );
  return m;
}

function helloRules(hello: HelloMsg): Rules {
  // The engine can change while the rules stay the same, so the rules alone can't vouch for it.
  // A hello from before the ladder sent its engine version has none to compare.
  const engine = (hello as Partial<HelloMsg>).engine_version;
  if (engine !== undefined && engine !== ENGINE_VERSION)
    throw new Error(
      `forward: this match runs engine ${engine}, but this simulator has engine ${ENGINE_VERSION}; its steps would not be the ladder's. Install the ladder's simulator (GET /api → simulator)`,
    );
  return loadRules(hello.rules);
}

/**
 * The match's state on its first tick, exactly as the ladder starts it. The hello names the map
 * and carries the seed, which decides the spawns, so nothing about the start is hidden.
 */
function start(hello: HelloMsg, map?: GameMap): MatchState {
  return createMatch(helloRules(hello), helloMap(hello, map), hello.seed_public);
}

function projectileState(rules: Rules, p: ProjectileView): Projectile {
  const d: [number, number] = [p.target[0] - p.origin[0], p.target[1] - p.origin[1]];
  // Along the ray's major axis a shot moves exactly one SUB unit per unit travelled.
  const axis = Math.abs(d[0]) >= Math.abs(d[1]) ? 0 : 1;
  const traveled = Math.abs(p.exact_pos[axis]! - p.origin[axis]! * SUB);
  const range = rules.attacks[p.attack]?.range;
  return {
    id: p.id,
    owner: p.owner,
    attack: p.attack,
    origin: [p.origin[0], p.origin[1]],
    target: [p.target[0], p.target[1]],
    traveled,
    // After a bounce the engine keeps only the range left, which no observation shows; the
    // shipped shot has no range, so this is exact for it.
    max_travel: range === undefined ? UNLIMITED_TRAVEL : range * SUB,
    pos: [p.pos[0], p.pos[1]],
    exact_pos: [p.exact_pos[0], p.exact_pos[1]],
    speed: p.speed,
    damage: p.damage,
    bounces_left: p.bounces_left,
  };
}

function areaState(rules: Rules, tick: number, a: Omit<AreaView, "tiles">): Area {
  const explodes = tick + a.ticks_left - 1;
  const atk = rules.attacks[a.attack];
  const fuse = atk?.kind === "area" ? atk.fuse : 0;
  return {
    id: a.id,
    owner: a.owner,
    attack: a.attack,
    pos: [a.pos[0], a.pos[1]],
    // Where it was thrown from isn't shown and changes nothing once it lands.
    origin: [a.pos[0], a.pos[1]],
    launched_tick: explodes - fuse,
    explodes_tick: explodes,
    radius: a.radius,
    damage: a.damage,
    slow: a.slow,
  };
}

const untilTick = (tick: number, left: Record<string, number>) =>
  Object.fromEntries(Object.entries(left).map(([k, n]) => [k, tick + n - 1]));

/**
 * A state that agrees with everything `obs` shows, for fighter `hello.bot_id` on this tick. What
 * it doesn't show comes from `assume`, otherwise from a cautious default: an enemy in sight has
 * every attack ready (only its dash is shown), a pad out of sight is stocked, nothing is flying out
 * of sight. An enemy out of sight needs `assume.enemy.pos`: where you think it is, which is the
 * guess that matters most.
 */
function fromObservation(
  hello: HelloMsg,
  obs: Observation,
  assume: Assumptions = {},
  map?: GameMap,
): MatchState {
  const rules = helloRules(hello);
  const state = createMatch(rules, helloMap(hello, map), hello.seed_public);
  const tick = obs.tick;
  state.tick = tick;
  state.zone = { center: [obs.zone.center[0], obs.zone.center[1]], radius: obs.zone.radius };

  const me = state.fighters.find((f) => f.id === hello.bot_id);
  const enemy = state.fighters.find((f) => f.id !== hello.bot_id);
  if (!me || !enemy) throw new Error(`forward: no fighter ${hello.bot_id} in this match`);
  const s = obs.self;
  Object.assign(me, {
    pos: [s.pos[0], s.pos[1]],
    hp: s.hp,
    state: s.state,
    state_end: s.state_ticks_left > 0 ? tick + s.state_ticks_left - 1 : 0,
    cooldowns: { ...me.cooldowns, ...s.cooldowns },
    buffs: untilTick(tick, s.buffs),
    ticks_outside: assume.self?.ticks_outside ?? 0,
    damage_dealt: assume.self?.damage_dealt ?? 0,
    alive: s.hp > 0,
  });

  const seen = obs.enemies.find((e) => e.id === enemy.id);
  const guess = assume.enemy ?? {};
  const pos = seen?.pos ?? guess.pos;
  if (!pos)
    throw new Error(
      "forward: the enemy is out of sight; pass assume.enemy.pos (where you believe it is)",
    );
  const stateName = seen?.state ?? guess.state ?? "idle";
  const ticksLeft = seen?.state_ticks_left ?? guess.state_ticks_left ?? 0;
  Object.assign(enemy, {
    pos: [pos[0], pos[1]],
    hp: seen?.hp ?? guess.hp ?? rules.stats.max_hp,
    state: stateName,
    state_end: ticksLeft > 0 ? tick + ticksLeft - 1 : 0,
    // Unknown cooldowns default to 0: an enemy that could fire is the safe one to plan against.
    cooldowns: {
      ...Object.fromEntries(Object.keys(enemy.cooldowns).map((k) => [k, 0])),
      ...guess.cooldowns,
      ...(seen ? { dash: seen.dash_cooldown } : {}),
    },
    buffs: untilTick(tick, seen?.buffs ?? guess.buffs ?? {}),
    ticks_outside: guess.ticks_outside ?? 0,
    damage_dealt: guess.damage_dealt ?? 0,
  });

  const shown = new Map(obs.pickups.map((p) => [p.id, p.ready_in]));
  const stocked = rules.pickups ? rules.pickups.first_spawn : 0;
  for (const pad of state.pickups) {
    const readyIn =
      shown.get(pad.id) ?? assume.pickups?.[pad.id]?.ready_in ?? Math.max(0, stocked - tick);
    pad.available = readyIn <= 0;
    pad.respawn_tick = readyIn <= 0 ? pad.respawn_tick : tick + readyIn;
  }

  const shots = new Map<number, ProjectileView>();
  for (const p of [...(assume.projectiles ?? []), ...obs.projectiles]) shots.set(p.id, p);
  state.projectiles = [...shots.values()]
    .sort((a, b) => a.id - b.id)
    .map((p) => projectileState(rules, p));
  const areas = new Map<number, Omit<AreaView, "tiles">>();
  for (const a of [...(assume.areas ?? []), ...obs.areas]) areas.set(a.id, a);
  state.areas = [...areas.values()]
    .sort((a, b) => a.id - b.id)
    .map((a) => areaState(rules, tick, a));
  // Ids only name things; the next one just has to be new.
  state.next_projectile_id =
    Math.max(0, ...state.projectiles.map((p) => p.id), ...state.areas.map((a) => a.id)) + 1;
  return state;
}

/** The forward model. Every function takes and returns plain data; only `step` changes its argument. */
export const forward = {
  api: FORWARD_API_VERSION,
  start,
  fromObservation,
  /** A copy to step without touching the original (the rules and map are shared, never changed). */
  clone: cloneState,
  /**
   * Resolves one tick in place with each fighter's turn and returns its events. Each turn is
   * validated as the ladder does: an illegal part is dropped (and reported as a `rejected` event),
   * the rest is played. Throws once the match is over (`state.result` is set).
   */
  step(state: MatchState, turns: ForwardTurns): GameEvent[] {
    return step(state, turns);
  },
  /** What fighter `id` is told on this tick: the observation it would receive, without the server's budget and events. */
  observe,
  /** The steps and dashes fighter `id` could start now (the observation's `moves` and `dashes`). */
  options(state: MatchState, id: number): MoveOptions {
    const f = state.fighters.find((x) => x.id === id);
    if (!f) throw new Error(`forward: no fighter ${id}`);
    return moveOptions(state, f);
  },
  /** How the engine would take fighter `id`'s turn now: the parts it plays and those it refuses. */
  validate(state: MatchState, id: number, turn: TurnInput | null | undefined): Validation {
    const f = state.fighters.find((x) => x.id === id);
    if (!f) throw new Error(`forward: no fighter ${id}`);
    return validateTurn(state, f, turn);
  },
  /** The ladder's hash of the whole state, as recorded with every replay tick. */
  hash: stateHash,
};
export type Forward = typeof forward;
export type { MatchState as ForwardState };
