// A whole match in-process, for training: no server, no sockets, no clocks. Every reply takes the
// wire's path (JSON, the protocol's schema, then MatchCore, as on the ladder) and every message
// comes back as the JSON a bot would have received, so a policy trained here sees what it sees
// on the ladder. House bots play their real code, with the same context runBot gives them.

import {
  cloneState,
  type GameMap,
  type MatchResult,
  type MatchState,
  type Observation,
  type Replay,
  type Rules,
} from "@arena/engine";
import type { EndMsg, HelloMsg } from "@arena/protocol";
import {
  MatchCore,
  frameOutcome,
  type Limits,
  type MatchSummary,
  type TurnOutcome,
} from "./match.ts";
import { botReplies, frameOf, resolveBot, type SimBot } from "./plugins.ts";
import { SHIPPED_MAPS, SHIPPED_RULES } from "./shipped.ts";
import { wire } from "./wire.ts";

export interface GameOptions {
  /** decides the spawns and, unless `map` is given, the map (default 0) */
  seed?: number;
  /** a shipped map's name, or a map of your own; by default the seed picks one, as the ladder does */
  map?: string | GameMap;
  /** default: the shipped rules */
  rules?: Rules;
  /** a bot to play fighter 2: a house bot's name, a registered bot's, or a `SimBot`; without one you play both fighters (self-play) */
  opponent?: string | SimBot;
  /** the deadlines hello reports and the failed ticks that disqualify; default: the rules' limits */
  limits?: Partial<Limits>;
  /** the name and version the replay records for your fighters */
  name?: string;
  version?: string;
}

/** A turn as a bot sends it: an object (its `tick` is filled in when missing), the raw frame, or null for no reply. */
export type Reply = Record<string, unknown> | string | null;

/** What a fighter is sent next: an observation that asks for its turn, or the end of the match. */
export type NextMessage = Observation | EndMsg;

export function shippedMap(name: string): GameMap {
  const map = SHIPPED_MAPS.find((m) => m.name === name);
  if (!map)
    throw new Error(
      `unknown map '${name}' (shipped: ${SHIPPED_MAPS.map((m) => m.name).join(", ")})`,
    );
  return map;
}

/** A bot playing a seat inside the match (a house bot with the context `runBot` would give it). */
export interface HouseSeat {
  fighterId: number;
  /** its reply to an observation, as the frame it sends */
  reply: (obs: Observation) => string | null;
  /** its observation this tick, as it arrives over the wire */
  obs: Observation | null;
}

/**
 * A match as the ladder starts it: the map (by seed unless named), the seats, and each fighter's
 * hello. Shared by `Game` and the fast `VectorBatch`, so both start matches the same way.
 */
export function setUpMatch(
  opts: GameOptions,
  hashes = true,
): { core: MatchCore; players: number[]; hellos: Map<number, HelloMsg>; house: HouseSeat | null } {
  const seed = opts.seed ?? 0;
  const rules = opts.rules ?? SHIPPED_RULES;
  const n = SHIPPED_MAPS.length;
  const map =
    typeof opts.map === "object"
      ? opts.map
      : opts.map
        ? shippedMap(opts.map)
        : SHIPPED_MAPS[((seed % n) + n) % n]!;
  const you = { name: opts.name ?? "player", version: opts.version ?? "sim" };
  const bot = opts.opponent ? resolveBot(opts.opponent) : null;
  const players = bot ? [1] : [1, 2];
  const seats = [
    { fighterId: 1, ...you },
    bot
      ? { fighterId: 2, name: bot.name, version: bot.bot.version ?? "1" }
      : { fighterId: 2, ...you },
  ];
  const core = new MatchCore({
    matchId: `sim-${seed}`,
    rules,
    map,
    seed,
    limits: { ...rules.limits, ...opts.limits },
    seats,
    hashes,
  });
  const hellos = new Map(seats.map((s) => [s.fighterId, wire<HelloMsg>(core.hello(s.fighterId))]));
  const house = bot
    ? { fighterId: 2, reply: botReplies(bot.bot, hellos.get(2)!), obs: null }
    : null;
  return { core, players, hellos, house };
}

export class Game {
  /** the fighters you play */
  readonly players: number[];
  private core: MatchCore;
  private hellos: Map<number, HelloMsg>;
  /** what each player has been sent and not yet answered, as the frame and (once read) parsed */
  private frames = new Map<number, string>();
  private parsed = new Map<number, NextMessage>();
  private house: HouseSeat | null;

  constructor(opts: GameOptions = {}) {
    const m = setUpMatch(opts);
    this.players = m.players;
    this.core = m.core;
    this.hellos = m.hellos;
    this.house = m.house;
    this.ask();
  }

  /** The match's `hello` as fighter `id` receives it. */
  hello(id: number): HelloMsg {
    const h = this.hellos.get(id);
    if (!h) throw new Error(`no fighter ${id}`);
    return h;
  }

  /** What fighter `id` has been sent and not yet answered: this tick's observation, or `end` once the match is over. */
  next(id: number): NextMessage {
    let m = this.parsed.get(id);
    if (!m) this.parsed.set(id, (m = JSON.parse(this.nextFrame(id)) as NextMessage));
    return m;
  }

  /** `next` as the JSON text frame a bot receives. */
  nextFrame(id: number): string {
    if (!this.players.includes(id))
      throw new Error(`you don't play fighter ${id} (players: ${this.players.join(", ")})`);
    let f = this.frames.get(id);
    // The end message carries the match's stats, which take a pass over the replay: built only when read.
    if (f === undefined)
      this.frames.set(
        id,
        (f = JSON.stringify(this.core.endMessage(id, this.core.summary(), null))),
      );
    return f;
  }

  get over(): boolean {
    return this.core.result !== null;
  }

  get result(): MatchResult | null {
    return this.core.result;
  }

  /**
   * Resolves the tick with each player's reply, keyed by fighter id; a missing reply is no reply
   * (a timeout, as on the ladder). Then `next` has what each player is sent next.
   */
  step(replies: Record<number, Reply>): void {
    if (this.over) throw new Error("the match is over");
    const tick = this.core.state.tick;
    const outcomes: Record<number, TurnOutcome> = {};
    for (const id of this.players)
      outcomes[id] = frameOutcome(frameOf(replies[id] ?? null, tick), tick);
    const h = this.house;
    if (h) outcomes[h.fighterId] = frameOutcome(h.reply(h.obs!), tick);
    this.core.resolve(outcomes);
    this.frames.clear();
    this.parsed.clear();
    if (!this.over) this.ask();
  }

  /**
   * A copy of the whole match state as it stands, fog and all: what `forward` steps. For
   * training and testing a search with the truth; on the ladder a bot only has its observations.
   */
  state(): MatchState {
    return cloneState(this.core.state);
  }

  /** The finished match: result, replay and stats. */
  summary(): MatchSummary {
    return this.core.summary();
  }

  /** The finished match's replay, for `encodeReplay`, the viewer and `arena replay`. */
  replay(): Replay {
    return this.core.summary().replay;
  }

  /** Sends every fighter this tick's observation. */
  private ask(): void {
    for (const id of this.players)
      this.frames.set(id, JSON.stringify(this.core.takeObservation(id)));
    if (this.house) this.house.obs = wire(this.core.takeObservation(this.house.fighterId));
  }
}
