// The Python package's `Basic` encoding (arena_sim/encoding.py), written again here so the fast
// environments can encode inside the simulator, straight into typed arrays, instead of sending
// JSON to Python to be encoded there. Both read an observation as the ladder sends it, and a
// test in the Python package checks they give the same arrays, value for value.

import type { Observation, Rules, TurnInput } from "@arena/engine";

export const BASIC_CHANNELS = [
  "wall",
  "self",
  "enemy",
  "my_shots",
  "enemy_shots",
  "danger",
  "areas",
  "outside_zone",
  "pickups",
] as const;
export const BASIC_FEATURES = [
  "hp",
  "enemy_seen",
  "enemy_hp",
  "cd_move",
  "cd_dash",
  "cd_ranged",
  "cd_frostburst",
  "cd_repulsor",
  "idle",
  "state_ticks",
  "slowed",
  "power",
  "enemy_dash_cd",
  "enemy_idle",
  "enemy_slowed",
  "enemy_power",
  "time",
  "zone_radius",
  "shrinks_in",
] as const;
export const BASIC_ATTACKS = [null, "ranged", "frostburst", "repulsor"] as const;
export const BASIC_ACTIONS = 17 * BASIC_ATTACKS.length;

const DIRS = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"] as const;
const DIR_INDEX = Object.fromEntries(DIRS.map((d, i) => [d, i])) as Record<
  (typeof DIRS)[number],
  number
>;
const COOLDOWNS = ["move", "dash", "ranged", "frostburst", "repulsor"] as const;
const C = Object.fromEntries(BASIC_CHANNELS.map((name, i) => [name, i])) as Record<
  (typeof BASIC_CHANNELS)[number],
  number
>;

const clip = (v: number) => Math.min(Math.max(v, 0), 1);

/**
 * Where one seat's arrays start: the grid is channels × size × size, then the features, then 17
 * movements × 4 attacks. The grid holds `Basic`'s values, or with `codes` a byte per tile that
 * `decodeBasicGrid` turns back into them.
 */
export interface BasicSlot {
  grid: Float32Array | Uint8Array;
  vec: Float32Array;
  mask: Int8Array;
  /** index of this seat's first value in each array */
  at: { grid: number; vec: number; mask: number };
}

/** The danger channel's code is the ticks until the hit plus one, up to this. */
export const BASIC_DANGER_CODE_MAX = 255;

export class BasicEncoder {
  readonly size: number;
  readonly gridSize: number;
  /** write a byte per tile instead of the value: twice the value, or for danger the ticks until the hit plus one */
  readonly codes: boolean;
  private one: number;
  private walls = new Map<string, Float32Array | Uint8Array>();

  constructor(size = 21, codes = false) {
    this.size = size;
    this.gridSize = BASIC_CHANNELS.length * size * size;
    this.codes = codes;
    this.one = codes ? 2 : 1;
  }

  private wallGrid(mapName: string, tiles: string[]): Float32Array | Uint8Array {
    let grid = this.walls.get(mapName);
    if (!grid) {
      if (tiles.length > this.size || tiles[0]!.length > this.size)
        throw new Error(`map ${mapName} is larger than the encoder's ${this.size} tiles`);
      grid = (
        this.codes ? new Uint8Array(this.size * this.size) : new Float32Array(this.size * this.size)
      ).fill(this.one); // padding is wall
      tiles.forEach((row, y) => {
        for (let x = 0; x < row.length; x++)
          grid![y * this.size + x] = row[x] === "#" ? this.one : 0;
      });
      this.walls.set(mapName, grid);
    }
    return grid;
  }

  /**
   * Writes `obs` into one seat's place in the batch arrays: the grid, the features and the action
   * mask. Called for every seat every tick, so it builds as little as it can.
   */
  encode(
    obs: Observation,
    map: { name: string; tiles: string[] },
    rules: Rules,
    out: BasicSlot,
  ): void {
    const n = this.size;
    const { grid, vec, mask } = out;
    const g = out.at.grid;
    const me = obs.self;
    // The wall and zone channels are written whole; the rest start empty.
    grid.set(this.wallGrid(map.name, map.tiles), g + C.wall * n * n);
    grid.fill(0, g + C.self * n * n, g + C.outside_zone * n * n);
    grid.fill(0, g + C.pickups * n * n, g + this.gridSize);
    this.put(grid, g, C.self, me.pos, 1);
    for (const e of obs.enemies) this.put(grid, g, C.enemy, e.pos, 1);
    for (const p of obs.projectiles)
      this.put(grid, g, p.owner === me.id ? C.my_shots : C.enemy_shots, p.pos, 1);
    for (const d of obs.danger) this.putDanger(grid, g, d.tile, d.tick - obs.tick);
    for (const a of obs.areas)
      for (const tile of a.tiles) this.put(grid, g, C.areas, tile, a.owner !== me.id ? 1 : 0.5);
    const z = obs.zone;
    const zone = g + C.outside_zone * n * n;
    for (let y = 0; y < n; y++)
      for (let x = 0; x < n; x++) {
        const dist = Math.max(Math.abs(x - z.center[0]), Math.abs(y - z.center[1]));
        // outside now, or half for outside after the coming shrink
        grid[zone + y * n + x] =
          dist > z.radius
            ? this.one
            : z.next_radius !== null && dist > z.next_radius
              ? this.one / 2
              : 0;
      }
    for (const p of obs.pickups) if (p.ready_in === 0) this.put(grid, g, C.pickups, p.pos, 1);

    // Reading past the end of an empty list would make V8 throw away its compiled code, every time.
    const enemy = obs.enemies.length > 0 ? obs.enemies[0] : undefined;
    const cd = me.cooldowns;
    let v = out.at.vec;
    vec[v++] = me.hp / me.max_hp;
    vec[v++] = enemy ? 1 : 0;
    vec[v++] = enemy ? enemy.hp / me.max_hp : 0;
    for (const k of COOLDOWNS) vec[v++] = clip((cd[k] ?? 0) / 20);
    vec[v++] = me.state === "idle" ? 1 : 0;
    vec[v++] = clip(me.state_ticks_left / 10);
    vec[v++] = clip(me.slow_ticks_left / 10);
    vec[v++] = "power" in me.buffs ? 1 : 0;
    vec[v++] = enemy ? clip(enemy.dash_cooldown / 20) : 0;
    vec[v++] = enemy && enemy.state === "idle" ? 1 : 0;
    vec[v++] = enemy ? clip(enemy.slow_ticks_left / 10) : 0;
    vec[v++] = enemy && "power" in enemy.buffs ? 1 : 0;
    vec[v++] = obs.tick / rules.max_ticks;
    vec[v++] = clip(z.radius / n);
    vec[v++] = z.shrinks_in === null ? 1 : clip(z.shrinks_in / 50);

    // Exact for movement, cooldowns and the frostburst's range, which counts from the tile the
    // movement ends on. Line of sight for a frostburst is left to the engine, as in Basic.
    // Movements are standing still, then a step toward each of DIRS, then a dash toward each.
    const row = BASIC_ATTACKS.length;
    mask.fill(0, out.at.mask, out.at.mask + 17 * row);
    const idle = me.state === "idle";
    const ranged = idle && (cd.ranged ?? 0) === 0 && enemy !== undefined;
    const frost = idle && (cd.frostburst ?? 0) === 0 && enemy !== undefined;
    const repulsor = idle && (cd.repulsor ?? 0) === 0;
    const reach = rules.attacks.frostburst?.kind === "area" ? rules.attacks.frostburst.range : 0;
    const allow = (movement: number, end: readonly [number, number]) => {
      const at = out.at.mask + movement * row;
      mask[at] = 1;
      mask[at + 1] = ranged ? 1 : 0;
      mask[at + 2] =
        frost &&
        Math.max(Math.abs(end[0] - enemy!.pos[0]), Math.abs(end[1] - enemy!.pos[1])) <= reach
          ? 1
          : 0;
      mask[at + 3] = repulsor ? 1 : 0;
    };
    allow(0, me.pos);
    for (const m of obs.moves) allow(1 + DIR_INDEX[m.dir], m.tile);
    for (const d of obs.dashes) allow(9 + DIR_INDEX[d.dir], d.tile);
  }

  /** The index of a tile in a channel, or -1: projectiles and blasts can reach past the map's edge, and those tiles aren't on the grid. */
  private index(g: number, channel: number, pos: readonly [number, number]): number {
    const n = this.size;
    const x = pos[0];
    const y = pos[1];
    return x < 0 || x >= n || y < 0 || y >= n ? -1 : g + (channel * n + y) * n + x;
  }

  /** Raises one grid tile to `value` (1 or 0.5). */
  private put(
    grid: Float32Array | Uint8Array,
    g: number,
    channel: number,
    pos: readonly [number, number],
    value: number,
  ): void {
    const i = this.index(g, channel, pos);
    const v = value * this.one;
    if (i >= 0 && v > grid[i]!) grid[i] = v;
  }

  /** Marks a tile hit in `ticks` ticks (0 = the tick replied to): 1 / (1 + ticks), the soonest hit winning. */
  private putDanger(
    grid: Float32Array | Uint8Array,
    g: number,
    pos: readonly [number, number],
    ticks: number,
  ): void {
    const i = this.index(g, C.danger, pos);
    if (i < 0) return;
    if (!this.codes) {
      const v = 1 / (1 + ticks);
      if (v > grid[i]!) grid[i] = v;
      return;
    }
    const code = Math.min(BASIC_DANGER_CODE_MAX, 1 + ticks);
    if (grid[i] === 0 || code < grid[i]!) grid[i] = code;
  }
}

/**
 * `Basic`'s grid from a coded one, value for value: a danger code c is 1 / c (0 for none), any
 * other code is half its value. Danger more than BASIC_DANGER_CODE_MAX - 1 ticks away reads as
 * 1 / BASIC_DANGER_CODE_MAX, the one place the codes are not exact.
 */
export function decodeBasicGrid(
  codes: Uint8Array,
  size = 21,
  out = new Float32Array(codes.length),
): Float32Array {
  const plane = size * size;
  const per = BASIC_CHANNELS.length * plane;
  for (let i = 0; i < codes.length; i++) {
    const c = codes[i]!;
    out[i] = Math.floor((i % per) / plane) === C.danger ? (c === 0 ? 0 : 1 / c) : c / 2;
  }
  return out;
}

/** The turn an action stands for: `movement * 4 + attack`, aimed at the first enemy in sight. */
export function basicTurn(action: number, obs: Observation): TurnInput {
  const row = BASIC_ATTACKS.length;
  const movement = Math.floor(action / row);
  const name = BASIC_ATTACKS[action % row];
  const turn: TurnInput = {};
  if (movement >= 1 && movement <= 8) turn.move = DIRS[movement - 1];
  else if (movement >= 9) turn.dash = DIRS[movement - 9];
  if (name === "repulsor") turn.attack = { name };
  else if (name && obs.enemies.length > 0)
    turn.attack = { name, target: [obs.enemies[0]!.pos[0], obs.enemies[0]!.pos[1]] };
  return turn;
}
