// Recorded matches through an encoder: imitation data (what each bot saw, as your network reads
// it, and the action closest to what it did), and a check that an encoder reads the ladder's JSON
// exactly as it reads the batch's observations, so a policy trained on one plays the other.

import { checkCompatible, type Observation, type RecordedTurn, type Replay } from "@arena/engine";
import type { HelloMsg } from "@arena/protocol";
import { MatchCore, recordedOutcome, type TurnOutcome } from "./match.ts";
import { gridLength, type EncoderOutput, type SimEncoder, type TurnReply } from "./plugins.ts";
import type { VectorSpec } from "./vector.ts";
import { wire } from "./wire.ts";

/** Every tick of a replay, as each fighter was sent it (the observation object the match built) and the turn the server took. */
function* replaySteps(
  replay: Replay,
): Generator<
  { hellos: Map<number, HelloMsg> } | { fighter: number; obs: Observation; turn: RecordedTurn }
> {
  const { header } = replay;
  const { rules, map } = checkCompatible(header);
  const seats = header.bots.map((b) => ({ fighterId: b.id, name: b.name, version: b.version }));
  const core = new MatchCore({
    matchId: "replay",
    rules,
    map,
    seed: header.seed,
    limits: rules.limits,
    seats,
  });
  yield {
    hellos: new Map(seats.map((s) => [s.fighterId, wire<HelloMsg>(core.hello(s.fighterId))])),
  };
  for (const t of replay.ticks) {
    if (core.result) throw new Error(`replay: tick ${t.tick} recorded after the match ended`);
    if (t.tick !== core.state.tick)
      throw new Error(`replay: tick ${t.tick} recorded where tick ${core.state.tick} was expected`);
    const outcomes: Record<number, TurnOutcome> = {};
    for (const s of seats) {
      const turn = t.turns[String(s.fighterId)] ?? { reason: "timeout" };
      yield { fighter: s.fighterId, obs: core.takeObservation(s.fighterId), turn };
      outcomes[s.fighterId] = recordedOutcome(turn);
    }
    core.resolve(outcomes);
  }
}

/** A recorded match encoded for learning, a row per fighter per tick, in one buffer like `VectorBatch`'s. */
export interface ReplayDataset {
  spec: VectorSpec;
  /** rows */
  steps: number;
  buffer: ArrayBuffer;
  /** where each array lives in `buffer`: a byte offset and a length in elements */
  layout: Record<
    "grid" | "vec" | "mask" | "action" | "fighter" | "tick",
    { offset: number; length: number }
  >;
}

/**
 * Each tick of a recorded match as `encoder` reads it, for each fighter in `fighters` (default:
 * both): the grid, numbers and mask, and `action`, the encoder's action closest to the turn the bot
 * sent (`action(turn)`, kept only if the mask allows it), or -1 where there is none: the bot timed
 * out or sent nothing usable, or its turn has no action that comes close. Throws for a replay from
 * another engine version or rules table.
 */
export function replayDataset(
  replay: Replay,
  encoder: SimEncoder,
  fighters?: number[],
): ReplayDataset {
  const keep = (id: number) => !fighters || fighters.includes(id);
  const steps = replay.ticks.length * replay.header.bots.filter((b) => keep(b.id)).length;
  const g = gridLength(encoder);
  const coded = encoder.gridType === "uint8";
  const sizes: [keyof ReplayDataset["layout"], number, number][] = [
    ["vec", steps * encoder.features, 4],
    ["action", steps, 4],
    ["fighter", steps, 4],
    ["tick", steps, 4],
    ["grid", steps * g, coded ? 1 : 4],
    ["mask", steps * encoder.actions, 1],
  ];
  sizes.sort((a, b) => b[2] - a[2]);
  const layout = {} as ReplayDataset["layout"];
  let offset = 0;
  for (const [name, length, bytes] of sizes) {
    layout[name] = { offset, length };
    offset += length * bytes;
  }
  const buffer = new ArrayBuffer(offset);
  const at = (name: keyof ReplayDataset["layout"]) =>
    [buffer, layout[name].offset, layout[name].length] as const;
  const grid = coded ? new Uint8Array(...at("grid")) : new Float32Array(...at("grid"));
  const vec = new Float32Array(...at("vec"));
  const mask = new Int8Array(...at("mask"));
  const action = new Int32Array(...at("action"));
  const fighter = new Int32Array(...at("fighter"));
  const tick = new Int32Array(...at("tick"));
  const seats = new Map<number, ReturnType<SimEncoder["start"]>>();
  let row = 0;
  for (const s of replaySteps(replay)) {
    if ("hellos" in s) {
      for (const [id, hello] of s.hellos) if (keep(id)) seats.set(id, encoder.start(hello));
      continue;
    }
    const seat = seats.get(s.fighter);
    if (!seat) continue;
    const out: EncoderOutput = {
      grid: grid.subarray(row * g, (row + 1) * g),
      vec: vec.subarray(row * encoder.features, (row + 1) * encoder.features),
      mask: mask.subarray(row * encoder.actions, (row + 1) * encoder.actions),
    };
    seat.encode(wire(s.obs), out);
    const { reason, ms: _ms, ...turn } = s.turn;
    let a = -1;
    if (!reason) {
      if (!seat.action)
        throw new Error("labelling actions needs an encoder whose seats have action(turn)");
      a = seat.action(turn as TurnReply);
      if (a < 0 || a >= encoder.actions || !out.mask[a]) a = -1;
    }
    action[row] = a;
    fighter[row] = s.fighter;
    tick[row] = s.obs.tick;
    row++;
  }
  return {
    spec: {
      gridShape: [...encoder.gridShape],
      gridType: coded ? "uint8" : "float32",
      features: encoder.features,
      actions: encoder.actions,
    },
    steps: row,
    buffer,
    layout,
  };
}

/** A difference `checkEncoder` found. */
export interface EncoderMismatch {
  fighter: number;
  tick: number;
  /** "grid", "vec" or "mask" at `index`, "turn" for action `index`, or "action" when action(turn(index)) isn't `index` */
  what: "grid" | "vec" | "mask" | "turn" | "action";
  index: number;
  detail: string;
}

/**
 * Checks an encoder on a recorded match: each fighter's observations go to one seat encoder as
 * the batch passes them (the objects the match builds) and to another as the ladder sends them
 * (parsed JSON), and every array, and the turn for every action the mask allows, must come out the
 * same. Also checks that `action(turn(a))` gives back `a`, which labelling a teacher's or a
 * recorded bot's turns relies on. Returns the steps checked and the first `limit` differences.
 */
export function checkEncoder(
  replay: Replay,
  encoder: SimEncoder,
  limit = 20,
): { steps: number; mismatches: EncoderMismatch[] } {
  const g = gridLength(encoder);
  const coded = encoder.gridType === "uint8";
  const outs = () => ({
    grid: coded ? new Uint8Array(g) : new Float32Array(g),
    vec: new Float32Array(encoder.features),
    mask: new Int8Array(encoder.actions),
  });
  const seats = new Map<
    number,
    { batch: ReturnType<SimEncoder["start"]>; ladder: ReturnType<SimEncoder["start"]> }
  >();
  const mismatches: EncoderMismatch[] = [];
  const differ = (a: number, b: number) => a !== b && !(Number.isNaN(a) && Number.isNaN(b));
  let steps = 0;
  for (const s of replaySteps(replay)) {
    if ("hellos" in s) {
      for (const [id, hello] of s.hellos)
        seats.set(id, {
          batch: encoder.start(hello),
          ladder: encoder.start(JSON.parse(JSON.stringify(hello))),
        });
      continue;
    }
    if (mismatches.length >= limit) break;
    const seat = seats.get(s.fighter)!;
    const a = outs();
    const b = outs();
    seat.batch.encode(s.obs, a);
    seat.ladder.encode(JSON.parse(JSON.stringify(s.obs)), b);
    steps++;
    const found = (what: EncoderMismatch["what"], index: number, detail: string) =>
      mismatches.length < limit &&
      mismatches.push({ fighter: s.fighter, tick: s.obs.tick, what, index, detail });
    for (const name of ["grid", "vec", "mask"] as const) {
      const x = a[name];
      const y = b[name];
      for (let i = 0; i < x.length; i++)
        if (differ(x[i]!, y[i]!))
          found(name, i, `${x[i]} from the batch's observation, ${y[i]} from the ladder's JSON`);
    }
    for (let act = 0; act < encoder.actions; act++) {
      if (!a.mask[act]) continue;
      const t1 = JSON.stringify(seat.batch.turn(act));
      const t2 = JSON.stringify(seat.ladder.turn(act));
      if (t1 !== t2)
        found("turn", act, `${t1} after the batch's observation, ${t2} after the ladder's JSON`);
      if (seat.ladder.action) {
        const back = seat.ladder.action(JSON.parse(t2) as TurnReply);
        if (back !== act) found("action", act, `action(${t2}) is ${back}`);
      }
    }
  }
  return { steps, mismatches };
}
